---@param schematicName string 模板文件名
---@param startPos Vector3 放置坐标
---@param reversalX boolean 是否基于x旋转
---@param reversalZ boolean 是否基于z旋转
---@param coverOldBlock boolean 是否覆盖旧方块
---@param placeRakssid number 放置模板的玩家rakssid
---@param placeBlockId number 替换的方块Id, 0=不替换
---@param axisRotation boolean|number 是否基于轴旋转
---@param extraParam number 额外参数，用于自定义事件对应逻辑
function EngineWorld:createSchematic(schematicName, startPos, reversalX, reversalZ, coverOldBlock, placeRakssid, placeBlockId, axisRotation, extraParam)
    
    if startPos and startPos.y < 0  then 
        return;
    end

    local schematicHeight = SchematicHeightInfo[schematicName]
    if schematicHeight and (schematicHeight + startPos.y) > 255 then
        return
    end
    
    reversalX = reversalX or false
    reversalZ = reversalZ or false
    if coverOldBlock == nil then
        coverOldBlock = true
    else
        coverOldBlock = false
    end
    placeRakssid = placeRakssid or 0
    placeBlockId = placeBlockId or 0
    if axisRotation == true then
        axisRotation = 1
    end
    axisRotation = axisRotation or 0
    extraParam = extraParam or 0
    World:createSchematic(schematicName, startPos, placeRakssid, reversalX, reversalZ, coverOldBlock, placeBlockId, axisRotation, extraParam)
end

---@param schematicName string 模板文件名
---@param startPos Vector3 放置坐标
---@param reversalX boolean 是否基于x旋转
---@param reversalZ boolean 是否基于z旋转
---@param placeRakssid number 放置模板的玩家rakssid
---@param axisRotation boolean|number 是否基于轴旋转
---@param extraParam number 额外参数，用于自定义事件对应逻辑
function EngineWorld:destroySchematic(schematicName, startPos, reversalX, reversalZ, placeRakssid, axisRotation, extraParam)
    reversalX = reversalX or false
    reversalZ = reversalZ or false
    placeRakssid = placeRakssid or 0
    if axisRotation == true then
        axisRotation = 1
    end
    axisRotation = axisRotation or 0
    extraParam = extraParam or 0
    World:destroySchematic(schematicName, startPos, placeRakssid, reversalX, reversalZ, axisRotation, extraParam)
end

